<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, useForm } from '@inertiajs/vue3'; const props=defineProps<{student?:any}>(); const form=useForm({first_name:props.student?.first_name||'',middle_name:props.student?.middle_name||'',last_name:props.student?.last_name||'',preferred_name:props.student?.preferred_name||'',status:props.student?.status||'active'}); const submit=()=>props.student?form.patch(route('students.update',props.student.id)):form.post(route('students.store'));</script>
<template><Head :title="student?'Edit student':'Add student'"/><AuthenticatedLayout><h1 class="h2">{{ student?'Edit student':'Add student' }}</h1><div class="card mt-4"><form class="card-body" @submit.prevent="submit"><div class="row g-3"><div class="col-md-6"><label class="form-label">First name</label><input v-model="form.first_name" class="form-control" required><div class="text-danger small">{{form.errors.first_name}}</div></div><div class="col-md-6"><label class="form-label">Last name</label><input v-model="form.last_name" class="form-control" required><div class="text-danger small">{{form.errors.last_name}}</div></div><div class="col-md-6"><label class="form-label">Middle name <span class="text-secondary">(optional)</span></label><input v-model="form.middle_name" class="form-control"></div><div class="col-md-6"><label class="form-label">Preferred name <span class="text-secondary">(optional)</span></label><input v-model="form.preferred_name" class="form-control"></div><div v-if="student" class="col-md-6"><label class="form-label">Status</label><select v-model="form.status" class="form-select"><option>active</option><option>inactive</option><option>archived</option></select></div></div><button class="btn btn-primary mt-4" :disabled="form.processing">Save student</button></form></div></AuthenticatedLayout></template>
